SourceCode.Declaration:
class METDebugPickingListRegistration extends RunBase
{
    DialogField pickingRouteIdField;
    WMSPickingRouteID pickingRouteId;

}

Method.Source:
public Object dialog()
{
    Dialog dialog = super();

    dialog.caption("Select picking list to register");
    pickingRouteIdField = dialog.addField(extendedTypeStr(WMSPickingRouteID));
    return dialog;
}

public boolean getFromDialog()
{
    pickingRouteId = pickingRouteIdField.value();
    return super();
}

public void run()
{
    WMSOrderTrans wmsOrderTrans;
    container conOrdTransRoute;
    Timezone tz = DateTimeUtil::getUserPreferredTimeZone();

    info(strFmt('Begin %1', DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), tz)));

    if (pickingRouteId)
    {
        ttsbegin;   

        while select WMSOrderTrans
            where WMSOrderTrans.routeId == pickingRouteId
        {
            conOrdTransRoute += [wmsOrderTrans.RecId];
        }

        if (conOrdTransRoute)
        {

            METDallasPicklistRegContract contract = new METDallasPicklistRegContract();
            contract.parmConOrderTrans(conOrdTransRoute);

            METPickingListRegistrationPostingJob service = new METPickingListRegistrationPostingJob();
            service.postPickListRegistration(contract);
        }
        else
        {
            Error('No WMSOrderTrans for routeId %1', pickingRouteId);
        }

        ttscommit;
    }

    info(strFmt('End %1', DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), tz)));
}

/// <summary>
/// Class entry point. The system will call this method when a designated menu
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    METDebugPickingListRegistration debugSOExtract = new METDebugPickingListRegistration();

    if (debugSOExtract.prompt())
    {
        debugSOExtract.run();
    }
}
